public void testPerfData() throws IOException {
    final String json = "{\n" + "  \"service\": \"test\",\n" + "  \"serviceVersion\": \"v0.0.1\",\n" + "  \"pagePath\": \"/e2e-browser\",\n" + "  \"redirectTime\": 1,\n" + "  \"dnsTime\": 2,\n" + "  \"ttfbTime\": 3,\n" + "  \"tcpTime\": 4,\n" + "  \"transTime\": 5,\n" + "  \"domAnalysisTime\": 6,\n" + "  \"fptTime\": 7,\n" + "  \"domReadyTime\": 8,\n" + "  \"loadPageTime\": 9,\n" + "  \"resTime\": 10,\n" + "  \"sslTime\": 11,\n" + "  \"ttlTime\": 12,\n" + "  \"firstPackTime\": 13,\n" + "  \"fmpTime\": 14\n" + "}";
    final BrowserPerfDataReportServletHandler reportServletHandler = new BrowserPerfDataReportServletHandler(moduleManager, null, null);
    when(request.getReader()).thenReturn(new BufferedReader(new StringReader(json)));
